import{_ as r,l,o as e,c as A,v as t,p as E,x as i,d as n,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"显影后对刻蚀后","description":"","frontmatter":{"title":"显影后对刻蚀后","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/adi-aei.md","filePath":"litho/adi-aei.md","lastUpdated":1789023840000}'),d={name:"litho/adi-aei.md"};function I(h,a,D,c,_,m){const o=l("Mermaid");return e(),A("div",null,[a[1]||(a[1]=t('<h1 id="显影后对刻蚀后" tabindex="-1">显影后对刻蚀后 <a class="header-anchor" href="#显影后对刻蚀后" aria-label="Permalink to &quot;显影后对刻蚀后&quot;">​</a></h1><div class="epigraph"><p>显影后的线宽是胶浮雕的尺寸；刻蚀后的线宽才是衬底上留下来的尺寸。两套 CD 差一截偏置，不能当同一个反馈回扫描机。</p><footer>—— 据 Levinson 对 after-develop / after-etch 计量与刻蚀偏置的区分整理</footer></div><p><a href="/litho/litho-process-flow">上一课</a>把转印链写成掩模 → 空中像 → 潜像 → 显影浮雕 → 刻蚀转印，并已经点名 ADI 与 AEI 必须分开报。缺口是：产线同时活着两套 CD，反馈回路、OPC 目标和故障隔离各认哪一套，还没有写成合同。本课钉显影后检验（ADI）对刻蚀后检验（AEI）。套刻是下一课的位置问题，不在这里重讲对准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一条栅，显影后 SEM 看到的是光刻胶顶（或某焦平面）的宽度；刻蚀、去胶之后，硬掩模或多晶硅上的宽度通常更窄或更宽，取决于横向侵蚀、聚合物沉积和选择比。上一课把这截差叫做刻蚀偏置。缺口不是再背一遍流程顺序，而是：扫描机的剂量/焦点该跟谁、刻蚀腔该跟谁、设计意图写在哪一套数上。</p><p>把 AEI 目标直接当成「镜头分辨率」，等于把腔室匹配算进 NA。把 ADI 当成出货尺寸，又会在电性上发现栅长短了一截。两套计量、两个班组、两个时间点，混用一张控制图就会振荡。</p><h3 id="偏置不是一个全球纳米数" tabindex="-1">偏置不是一个全球纳米数 <a class="header-anchor" href="#偏置不是一个全球纳米数" aria-label="Permalink to &quot;偏置不是一个全球纳米数&quot;">​</a></h3><p>刻蚀偏置随节距、开口率、胶厚、硬掩模栈和腔室老化变。密线与孤立线的偏置可以差出工艺窗的一截，于是出现「刻蚀邻近」：上一课光学链之外的又一层邻域。OPC 若只拟合 ADI，硅上最终轮廓仍会偏；若只拟合 AEI，扫描机当天的剂量漂移会被刻蚀噪声淹没。</p><p><span class="marginnote">ADI 本身已含 SEM 收缩、荷电与测量算法偏置。报「显影后 48 nm」必须声明机台、电压、算法。AEI 换材料衬度，偏置又换一套。两套数都不能当真空里的真值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>产线最小配置是：固定曝光矩阵量 ADI，同一批（或裂片）刻蚀后量 AEI，画 ADI–AEI 相关。均值差是偏置；斜率不是 1 时，说明刻蚀在放大或压缩光刻的 CD 变化——侧壁角与开口率在投票。控制策略通常拆环：扫描机/轨道盯 ADI（响应快、不含腔室），刻蚀盯 AEI 与偏置稳定性。长期把偏置送回 OPC 模型，而不是每个班次用 AEI 去拧激光能量。</p><p>设计规则与电学目标默认对着 AEI（或最终硅）。光刻工艺窗可以先用 ADI 画，但重叠窗必须声明「这是胶上的窗还是硅上的窗」。OPC 的前向模型若只校准到胶上，交付的是可显影的轮廓；要落到电性，还得再叠一层刻蚀模块，或直接拿 AEI 当目标。两套校准片、两次抽检，不能共用一张「CD 控制图」。<a href="/litho/lele-multipattern">多重图形</a>里，第一次 AEI 是第二次涂胶的衬底，反射与涂覆均匀性跟着变，更不能把第一次 ADI 当成第二次的起始形貌。</p><h3 id="两套图-两种故障" tabindex="-1">两套图，两种故障 <a class="header-anchor" href="#两套图-两种故障" aria-label="Permalink to &quot;两套图，两种故障&quot;">​</a></h3><p>ADI 飘、AEI 跟着飘：先查剂量、焦点、胶厚、PEB。ADI 稳、AEI 飘：查刻蚀腔、聚合物、射频小时数。AEI 好、电性仍差：可能是剖面（侧壁、残留）而不是顶视 CD。本课只要求按段隔离，不把良率写成步骤数的函数。</p>',14)),(e(),E(p,null,{default:i(()=>[s(o,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEV%5B%22%E6%98%BE%E5%BD%B1%E6%B5%AE%E9%9B%95%22%5D%20--%3E%20ADI%5B%22ADI%20CD%22%5D%0A%20%20ADI%20--%3E%20ET%5B%22%E5%88%BB%E8%9A%80%E8%BD%AC%E5%8D%B0%22%5D%0A%20%20ET%20--%3E%20AEI%5B%22AEI%20CD%22%5D%0A%20%20ADI%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%20%2F%20%E8%BD%A8%E9%81%93%E5%8F%8D%E9%A6%88%22%5D%0A%20%20AEI%20--%3E%20ETCH%5B%22%E5%88%BB%E8%9A%80%E8%85%94%E5%8F%8D%E9%A6%88%22%5D%0A%20%20AEI%20--%3E%20OPC%5B%22OPC%20%E7%9A%84%E6%9C%80%E7%BB%88%E7%9B%AE%E6%A0%87%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>胶当掩模时，等离子体同时打胶顶与侧壁。选择比高、各向异性好，偏置小；胶不够厚或侧壁不陡，横向吃掉的量变成 CD。硬掩模可以「冻结」一次中间 AEI，再往下刻时胶已经不在。转移函数还可以滤掉一部分线边粗糙、放大另一部分——所以「光刻 LWR」与「硅上 LWR」也要分开报，机制与本课的平均 CD 偏置平行。</p><p>开口率通过反应物消耗与副产物再沉积改局部速率，这就是刻蚀微负载。它看起来像 OPE，但换一台刻蚀机、不换镜头，曲线会动。故障隔离必须能做这个实验：同一批 ADI、两台腔室，AEI 若分叉，责任在转印段。侧壁角把顶视 ADI 与底宽 AEI 进一步拆开，后课剖面会写；本课只要记住顶视合格不等于底宽合格。</p><p><span class="marginnote">正胶 ADI 的「线」是留下的胶；刻蚀后的「线」可能是硬掩模或衬底。tone 在转印中可能再反一次（亮场切槽）。比较 ADI/AEI 前先确认量的是同一类图形的同一段。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲某家腔室的食谱，不把某一代 FinFET 的偏置写成定律。也不讨论注入层（无「AEI 线宽」、只有阻挡图形）。计量课会展开 CD-SEM 与散射测量；本课只钉两套时间点。下一课的套刻同样有「光刻后 / 刻蚀后」标记位移，机制类似，对象换成位置。</p><p>不要发明「AEI = ADI × 0.9 则良率合格」之类换算。偏置由工艺包标定。出处里的 Levinson 把 after-develop 与 after-etch 当作不同检验站，而不是同一个 SEM 数的别名。</p><p>下一课套刻同样有光刻后 / 刻蚀后标记位移。对象换成位置，隔离逻辑与本课的两套 CD 平行。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ADI 是胶浮雕 CD；AEI 是刻蚀后衬底/硬掩模 CD。</li><li>扫描机通常跟 ADI；设计意图与腔室匹配跟 AEI。</li><li>偏置随节距与开口率变，含刻蚀邻近，不得并进光学 OPE。</li><li>ADI 稳而 AEI 飘，先查刻蚀而不是 NA。</li><li>出处：Levinson, <em>Principles of Lithography</em>；Mack 对转印链末段的讨论。</li></ul>',10))])}const B=r(d,[["render",I]]);export{f as __pageData,B as default};
